	/**
	 * Default Constructor
	 */
    public PaymentService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PaymentEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PaymentRepository.class) );
		this.validator		= applicationContext.getBean(PaymentValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Payment
	 */
		public Payment createPayment( CreatePaymentCommand command ) {

		Payment entity = new Payment();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentId( command.getPaymentId() );
            entity.setPaymentNumber( command.getPaymentNumber() );
            entity.setAmount( command.getAmount() );
            entity.setTransactionId( command.getTransactionId() );
            entity.setAuthorizedAt( command.getAuthorizedAt() );
            entity.setCapturedAt( command.getCapturedAt() );
            entity.setStatus( command.getStatus() );
            entity.setPaymentMethod( command.getPaymentMethod() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Payment {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePaymentCommand
	 * @return		Payment
	 */
	public Payment updatePayment( UpdatePaymentCommand command ) {

		Payment entity = new Payment();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPaymentId( command.getPaymentId() );
            entity.setPaymentNumber( command.getPaymentNumber() );
            entity.setAmount( command.getAmount() );
            entity.setTransactionId( command.getTransactionId() );
            entity.setAuthorizedAt( command.getAuthorizedAt() );
            entity.setCapturedAt( command.getCapturedAt() );
            entity.setOrder( command.getOrder() );
            entity.setCustomer( command.getCustomer() );
            entity.setPaymentProvider( command.getPaymentProvider() );
            entity.setRefunds( command.getRefunds() );
            entity.setStatus( command.getStatus() );
            entity.setPaymentMethod( command.getPaymentMethod() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Payment {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePaymentCommand
	 */
	public void delete( DeletePaymentCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPaymentId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Payment {0} ", id );

	}

	/**
	 * Method to retrieve the Payment via PaymentFetchOneSummary
	 * @param 	summary PaymentFetchOneSummary
	 * @return 	PaymentFetchOneResponse
	 */
	public Payment getPayment( PaymentFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PaymentFetchOneSummary arg cannot be null" );

		Payment entity = null;
		UUID id = summary.getPaymentId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Payment using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Payments
	 *
	 * @return 	List<Payment>
	 */
    public List<Payment> getAllPayment() {
		List<Payment> list = projector.findAll( new FindAllPaymentQuery() );
		return list;
	}

	/**
	 * assign Order on Payment
	 * @param		command AssignOrderToPaymentCommand
	 */
	public void assignOrder( AssignOrderToPaymentCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrder(command.getPaymentId(), command.getAssignment());

	}

